window.AUTH=window.AUTH||{};window.AUTH["17-5639"]={"d":"17-5639","id":"2017/17-5639","n":"Chavez-Meza v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Adaucto Chavez-Meza","date":"2018-02-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-5639/40279/20180327175935274_Corrected%20Brief%20of%20Petitioner-%20Chavez-Meza%20No.%2017-5639.pdf","side":"pet","n":76},{"k":"respondent","label":"Brief of respondent United States","date":"2018-03-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-5639/40394/20180328144744330_17-5639bsUnitedStates.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioner Adaucto Chavez-Meza","date":"2018-04-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-5639/43340/20180413143049576_Chavez-Meza%20Merits%20Reply.pdf","side":"pet","n":39}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"by":{"0":"12, 13","2":"7, 8, 15"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"by":{"0":"2","1":"31"}},{"t":"case","label":"Burns v. United States","cite":"501 U.S. 129","y":1991,"id":"1990/89-7260","sc":1,"by":{"0":"18, 19","2":"14"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"by":{"0":"13","1":"34","2":"9"},"q":[{"src":"brief","b":0,"text":"on an erroneous view of the law or on a clearly erroneous assessment of the evidence.","cite":"496 U.S. 384, 405"}]},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"by":{"0":"passim","1":"passim","2":"3, 16"},"q":[{"src":"brief","b":0,"text":"congressional act of lenity [is] intended to give prisoners the benefit of later enacted adjustments to the judgments reflected in the Guidelines.","cite":"560 U.S. at 828"},{"src":"brief","b":0,"text":"not authorize a sentencing or resentencing proceeding,","cite":"560 U.S. at 825"},{"src":"brief","b":1,"text":"may then grant a reduction within the amended Guidelines range if it determines that one is warranted ‘after considering the factors set forth in section 3553(a) to the extent that they are applicable.’","cite":"560 U.S. at 822"},{"src":"brief","b":1,"text":"does not authorize a sentencing or resentencing proceeding.","cite":"560 U.S. at 825"},{"src":"argument","who":"Mr. Coberly","text":"And as the Court understood in Dillon, the purpose of Section 3582(c)(2) was to give prisoners the benefit of the Sentencing Commission's determination that there was a systemic problem with a particular guideline."},{"src":"argument","who":"Mr. Rosenstein","text":"It expressly incorporates 3553(a), which we recognize and the district court acknowledged, but it does not incorporate the procedural requirements. Now this Court affirmed that in the Dillon case, where -"},{"src":"argument","who":"Mr. Rosenstein","text":"And the reason -- the answer, Your Honor, as articulated by this Court in Dillon, is that we are not at a formal resentencing proceeding here."}]},{"t":"case","label":"Dorszynski v. United States","cite":"418 U.S. 424","y":1974,"id":"1973/73-5284","sc":1,"by":{"0":"19, 20","1":"19"},"q":[{"src":"brief","b":1,"text":"district courts generally had no obligation to state their reasons for imposing any particular sentence.","cite":"418 U.S. 424, 440-442"},{"src":"argument","who":"Mr. Rosenstein","text":"Again, this - the sentencing guidelines were adopted in 1984 against a backdrop of long-standing precedent of this Court, reflected most significantly in the Dorszynski case, where the Court indicated that in the absence of any statutory mandate, at common law, the court -- district courts had discretion to impose sentences anywhere up to the statutory maximum."},{"src":"argument","who":"Mr. Rosenstein","text":"It didn't overrule Dorszynski. And if it had, Your Honor, we submit that Rita well might have come out differently, because this Court ruled in Rita in 2007 that no explicit analysis is required of the 3553(a) factors."}]},{"t":"case","label":"Freeman v. United States","cite":"564 U.S. 522","y":2011,"id":"2010/09-10245","sc":1,"by":{"0":"11, 12, 25, 30","2":"16"},"q":[{"src":"brief","b":0,"text":"[t]he binding policy statement governing § 3582(c)(2) motions plac- es considerable limits on district court discretion.","cite":"564 U.S. 522, 531"}]},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"0":"13, 16, 25, 31","1":"21, 31, 33","2":"5, 11, 15, 18"},"q":[{"src":"brief","b":2,"text":"make an individualized assessment based on the facts presented.","cite":"552 U.S. at 50"},{"src":"argument","who":"Mr. Coberly","text":"And as the Court has understood in -- in -- from Booker, through Rita, through Gall, ultimately, what that means, is was the -- was the sentence reasonable?"},{"src":"argument","who":"Mr. Coberly","text":"No matter what, as the Court has made clear in Gall, within-guideline sentences, outside-guideline sentences, the district court has -- has an obligation to explain the reason for the sentence."},{"src":"argument","who":"Mr. Coberly","text":"And so what we're asking is -- is for the Court to apply the rule it has already applied in Rita and Gall. And that's -- it's simply sufficient explanation to allow for meaningful appellate review -"}]},{"t":"case","label":"Hensley v. Eckerhart","cite":"461 U.S. 424","y":1983,"id":"1982/81-1244","sc":1,"by":{"0":"14","1":"29","2":"6"}},{"t":"case","label":"Kent v. United States","cite":"383 U.S. 541","y":1966,"id":"1965/104","sc":1,"by":{"0":"19"}},{"t":"case","label":"Kerry v. Din","cite":"135 S. Ct. 2128","y":2015,"id":"2014/13-1402","sc":1,"by":{"0":"20"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"by":{"0":"30","1":"3"}},{"t":"case","label":"Liti v. C.I.R.","cite":"289 F.3d 1103","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/1103/","by":{"0":"28"}},{"t":"case","label":"Martin v. Franklin Capital Corp.","cite":"546 U.S. 132","y":2005,"id":"2005/04-1140","sc":1,"by":{"0":"13"},"q":[{"src":"brief","b":0,"text":"Discretion is not a whim, and limiting discretion according to legal standards helps promote the basic principle of justice that like cases should be decided alike.","cite":"546 U.S. 132, 139"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"2","1":"20, 26"},"q":[{"src":"brief","b":0,"text":"has the power to fix the sentence for a federal crime, and the scope of judicial discretion with respect to a sentence is subject to congressional control.","cite":"488 U.S. 361, 364"}]},{"t":"case","label":"Northcross v. Bd. of Educ.","cite":"412 U.S. 427","y":1973,"id":"1972/72-1164","sc":1,"by":{"0":"14, 22","1":"29","2":"6"}},{"t":"case","label":"Perdue v. Kenny A. ex rel. Winn","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"by":{"0":"14, 22","1":"29","2":"6"}},{"t":"case","label":"Piper Aircraft Co. v. Reyno","cite":"454 U.S. 235","y":1981,"id":"1981/80-848","sc":1,"by":{"0":"14"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"by":{"0":"25, 31","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"should set forth enough to satisfy the appellate court that he has considered the parties' arguments and has a reasoned basis for exercising his own legal decisionmaking authority.","cite":"551 U.S. 338, 356"},{"src":"brief","b":0,"text":"standard directs appellate courts to evaluate what motivated the district judge’s individualized sentencing decision.","cite":"551 U.S. at 364"},{"src":"brief","b":1,"text":"[c]ircumstances may well make clear that the judge rests his decision upon the Commission’s own reasoning that the Guidelines sentence is a proper sentence * * * in the typical case, and that the judge has found that the case before him is typical.","cite":"551 U.S. 338, 356-357"},{"src":"brief","b":1,"text":"The appropriateness of brevity or length, conciseness or detail, when to write, what to say, depends upon circumstances. Sometimes a judicial opinion responds to every argument; sometimes it does not; sometimes a judge simply writes the word ‘granted’ or ‘denied’ on the face of a motion while relying upon context and the parties’ prior arguments to make the reasons clear. The law leaves much, in this respect, to the judge’s own professional judgment.","cite":"551 U.S. at 356"},{"src":"brief","b":2,"text":"abuse-ofdiscretion standard directs appellate courts to evaluate what motivated the district judge’s individualized sentencing decision.","cite":"551 U.S. at 364"},{"src":"brief","b":2,"text":"fair to assume that the Guidelines, insofar as practicable, reflect a rough approximation of sentences that might achieve § 3553(a)’s objectives.","cite":"551 U.S. at 350"},{"src":"argument","who":"Mr. Coberly","text":"There's - oftentimes, as the Court recognized in Rita, how much explanation a district court judge needs to give depends so much on circumstances and context."},{"src":"argument","who":"Mr. Coberly","text":"And as the Court has understood in -- in -- from Booker, through Rita, through Gall, ultimately, what that means, is was the -- was the sentence reasonable?"},{"src":"argument","who":"Mr. Coberly","text":"And so what we're asking is -- is for the Court to apply the rule it has already applied in Rita and Gall. And that's -- it's simply sufficient explanation to allow for meaningful appellate review -"}]},{"t":"case","label":"Traxler v. Multnomah Cty.","cite":"596 F.3d 1007","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/1007/","by":{"0":"14"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"0":"23","1":"3, 19, 20, 31, 32"},"q":[{"src":"brief","b":1,"text":"irrespective of whether the trial judge sentences within or outside the Guidelines range,","cite":"543 U.S. at 260"},{"src":"argument","who":"Mr. Coberly","text":"And as the Court has understood in -- in -- from Booker, through Rita, through Gall, ultimately, what that means, is was the -- was the sentence reasonable?"},{"src":"argument","who":"Mr. Rosenstein","text":"Remember, keep in mind, of course, we're in a post-Booker context here. The district court is guided in part by the guidelines but is required to consider all the relevant 3553(a) factors, and at the original sentencing, that's precisely what the court said."},{"src":"argument","who":"Mr. Rosenstein","text":"We are at a motion for a reduction, which is -- this Court recognized in Dillon is not governed by the constitutional or remedial holding of Booker."}]},{"t":"case","label":"United States v. Borden","cite":"564 F.3d 100","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/564/100/","by":{"0":"12"}},{"t":"case","label":"United States v. Brown","cite":"497 F. App’x 196","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/497/196/","by":{"0":"27"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","by":{"0":"13"}},{"t":"case","label":"United States v. Carey","cite":"589 F.3d 187","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/589/187/","by":{"0":"31, 32"}},{"t":"case","label":"United States v. Chi., M., St. P. & P. R. Co.","cite":"294 U.S. 499","y":1935,"id":"scdb/1934-093","sc":1,"by":{"0":"15"}},{"t":"case","label":"United States v. Christie","cite":"736 F.3d 191","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/736/191/","by":{"0":"15","1":"25"}},{"t":"case","label":"United States v. Cruz","cite":"523 F.2d 473","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/523/473/","by":{"0":"20, 21"}},{"t":"case","label":"United States v. Dorrough","cite":"84 F.3d 1309","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/84/1309/","by":{"0":"6"}},{"t":"case","label":"United States v. Dunn","cite":"728 F.3d 1151","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/728/1151/","by":{"0":"12","1":"32","2":"11"}},{"t":"case","label":"United States v. Fisher","cite":"55 F.3d 481","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/481/","by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"Trust me, I considered the necessary factors and my decision reflects a reasoned judgment.","cite":"55 F.3d 481, 487"}]},{"t":"case","label":"United States v. Grier","cite":"475 F.3d 556","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/475/556/","by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"[t]he touchstone of reasonableness is whether the record as a whole reflects rational and meaningful consideration of the factors . . . .","cite":"475 F.3d 556, 571"}]},{"t":"case","label":"United States v. Hall","cite":"582 F.3d 816","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/582/816/","by":{"0":"12"}},{"t":"case","label":"United States v. Hernandez-Marfil","cite":"825 F.3d 410","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/825/410/","by":{"0":"12"}},{"t":"case","label":"United States v. Howard","cite":"644 F.3d 455","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/644/455/","by":{"0":"15","1":"25","2":"11"}},{"t":"case","label":"United States v. Kennedy","cite":"722 F.3d 439","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/722/439/","by":{"0":"12"}},{"t":"case","label":"United States v. LaBonte","cite":"70 F.3d 1396","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/70/1396/","by":{"0":"12"}},{"t":"case","label":"United States v. Lafayette","cite":"585 F.3d 435","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/585/435/","by":{"0":"25"}},{"t":"case","label":"United States v. Locklair","cite":"668 F. App’x 477","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/668/477/","by":{"0":"27"}},{"t":"case","label":"United States v. Marion","cite":"590 F.3d 475","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/590/475/","by":{"0":"15","1":"26","2":"6"}},{"t":"case","label":"United States v. Mateo","cite":"560 F.3d 152","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/560/152/","by":{"0":"12"}},{"t":"case","label":"United States v. Mathis-Gardner","cite":"783 F.3d 1286","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/783/1286/","by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"cannot just reflexively presume that the learned judge appropriately exercised his discretion and considered all of the relevant factors, because that would risk turning abuse of discretion review into merely a rubber stamp.","cite":"783 F.3d 1286, 1288-89"}]},{"t":"case","label":"United States v. Nelson","cite":"303 F. App’x 641","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/303/641/","by":{"0":"6"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers’ Coop.","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"by":{"0":"15"}},{"t":"case","label":"United States v. Pardue","cite":"36 F.3d 429","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/429/","by":{"0":"12"}},{"t":"case","label":"United States v. Peters","cite":"843 F.3d 572","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/843/572/","by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"[c]ourts have a general duty to explain their reasoning. . . . [N]othing in Dillon suggests that [appellate courts] should abrogate district courts’ general responsibility to provide some individualized legal reasoning.","cite":"843 F.3d 572, 582"}]},{"t":"case","label":"United States v. Piper","cite":"839 F.3d 1261","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/1261/","by":{"0":"12"}},{"t":"case","label":"United States v. Reyes-Hernandez","cite":"624 F.3d 405","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/624/405/","by":{"0":"30"}},{"t":"case","label":"United States v. Ruiz-Terrazas","cite":"477 F.3d 1196","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/477/1196/","by":{"0":"32","1":"11"},"q":[{"src":"brief","b":0,"text":"‘When imposing a sentence within the properly calculated Guidelines range, a district court must provide as Section 3553(c) indicates by its plain language, only a general statement noting the appropriate guideline range and how it was calculated’","cite":"477 F.3d at 1202"},{"src":"brief","b":1,"text":"persuaded that § 3582 does not require more explanation than was provided here.","cite":"477 F.3d 1196, 1201"}]},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"by":{"0":"21"}},{"t":"case","label":"United States v. Sanchez-Juarez","cite":"446 F.3d 1109","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/1109/","by":{"0":"32"}},{"t":"case","label":"United States v. Smalls","cite":"720 F.3d 193","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/720/193/","by":{"0":"12, 23, 24, 27","1":"26"}},{"t":"case","label":"United States v. Taylor","cite":"487 U.S. 326","y":1988,"id":"1987/87-573","sc":1,"by":{"0":"passim","1":"12, 27, 28, 29, 30, 31","2":"passim"},"q":[{"src":"brief","b":0,"text":"[A]buse-of-discretion review is not toothless; and it is entirely proper for a reviewing court to find an abuse of discretion when important factors . . . are ‘slighted.’","cite":"487 U.S. at 337"},{"src":"brief","b":0,"text":"[w]hether discretion has been abused depends, of course, on the bounds of the discretion and the principles that guide its exercise.","cite":"487 U.S. at 336"},{"src":"brief","b":1,"text":"clearly articulate [those factors’] effect in order to permit meaningful appellate review.","cite":"487 U.S. at 336"}]},{"t":"case","label":"United States v. Velazquez","cite":"482 F.2d 139","y":1973,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/482/139/","by":{"0":"21"}},{"t":"case","label":"United States v. Washington","cite":"739 F.3d 1080","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/1080/","by":{"0":"31","2":"18"}},{"t":"case","label":"United States v. Webb","cite":"565 F.3d 789","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/789/","by":{"0":"12, 25","1":"24"}},{"t":"case","label":"United States v. Webb","cite":"760 F.3d 513","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/760/513/","by":{"0":"12"}},{"t":"case","label":"United States v. Zanghi","cite":"209 F.3d 1201","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/209/1201/","by":{"0":"28"}},{"t":"case","label":"United States v. Zayas-Ortiz","cite":"808 F.3d 520","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/808/520/","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"2","1":"16, 17"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(c)","(c)(1)","(c)(2)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim","1":"31, 32, 31, 32, 31, 32, 31, 32, 31, 32, 31, 32","2":"passim, passim"},"q":[{"src":"brief","b":1,"text":"at the time of sentencing, [to] state in open court the reasons for its imposition of the particular sentence.","cite":"18 U.S.C. 3553(c)"},{"src":"brief","b":1,"text":"the reason for imposing a sentence at a particular point within the range.","cite":"18 U.S.C. 3553(c)(1)"}]},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)","(c)(2)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 8, 12, passim","1":"31, 32, 31, 32","2":"passim"},"q":[{"src":"brief","b":1,"text":"may not modify a term of imprisonment once it has been imposed.","cite":"18 U.S.C. 3582(c)"},{"src":"brief","b":1,"text":"sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o),","cite":"18 U.S.C. 3582(c)(2)"},{"src":"argument","who":"Mr. Rosenstein","text":"And in this case, in Section 3582, Congress decided to permit an expedited process and not to require all the procedures that Congress created for original sentencing."}]},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(e)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22","2":"13, 14"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(a)(3)"],"by":{"0":"29"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(B)","(b)(1)(A)(viii)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 3, 17, 17","1":"2, 3"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","stext":{"head":"§846. Attempt and conspiracy","paras":[[0,"Any person who attempts or conspires to commit any offense defined in this subchapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/846?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"2, 3"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)(1)(B)"],"by":{"0":"30"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(g)","(u)"],"by":{"0":"17, 3, 3"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","by":{"0":"14, 22"}},{"t":"rule","label":"Fed. R. Crim. P. 43","url":"https://www.law.cornell.edu/rules/frcrmp/rule_43","subs":["(b)(4)"],"by":{"0":"25"}},{"t":"case","label":"EC Term of Years Trust v. United States","cite":"550 U.S. 429","y":2007,"id":"2006/05-1541","sc":1,"by":{"1":"32"}},{"t":"case","label":"General Elec. Co. v. Joiner","cite":"522 U.S. 136","y":1997,"id":"1997/96-188","sc":1,"by":{"1":"38"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"by":{"1":"32"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"‘sentence sufficient, but not greater than necessary’ to comply with the sentencing purposes set forth in [18 U.S.C.] 3553(a)(2).","cite":"562 U.S. 476, 491"},{"src":"brief","b":1,"text":"although a sentencing court must ‘give respectful consideration to the Guidelines, Booker permits the court to tailor the sentence in light of other statutory concerns as well.’","cite":"562 U.S. at 490"}]},{"t":"case","label":"Sprint/United Mgmt. Co. v. Mendelsohn","cite":"552 U.S. 379","y":2008,"id":"2007/06-1221","sc":1,"by":{"1":"38","2":"8, 9, 19"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"This Court adheres to the general principle that Congress’ use of explicit language in one provision cautions against inferring the same limitation in another provision.","cite":"137 S. Ct. 436, 442"}]},{"t":"case","label":"Stinson v. United States","cite":"508 U.S. 36","y":1993,"id":"1992/91-8685","sc":1,"by":{"1":"6"}},{"t":"case","label":"United States v. Abel","cite":"469 U.S. 45","y":1984,"id":"1984/83-935","sc":1,"by":{"1":"30"}},{"t":"case","label":"United States v. Bowers","cite":"615 F.3d 715","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/615/715/","by":{"1":"31, 32","2":"10, 11"}},{"t":"case","label":"United States v. Evans","cite":"587 F.3d 667","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/587/667/","by":{"1":"26"}},{"t":"case","label":"United States v. Jones","cite":"846 F.3d 366","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/846/366/","by":{"1":"32","2":"11"}},{"t":"case","label":"United States v. Rodriguez","cite":"855 F.3d 526","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/855/526/","by":{"1":"32","2":"11"}},{"t":"case","label":"United States v. Verdin-Garcia","cite":"824 F.3d 1218","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/1218/","by":{"1":"10"},"q":[{"src":"brief","b":1,"text":"the need for a district court to create a meaningful basis for appellate review and to promote the perception of fairness.","cite":"824 F.3d 1218, 1222"}]},{"t":"case","label":"Walton v. Arizona","cite":"497 U.S. 639","y":1990,"id":"1989/88-7351","sc":1,"by":{"1":"34, 38","2":"8, 19"},"q":[{"src":"brief","b":1,"text":"know the law and * * * apply it in making their decisions.","cite":"497 U.S. 639, 653"},{"src":"argument","who":"Mr. Rosenstein","text":"But the second is that, under Walton v. Arizona, a long-standing principle, courts presume that district courts know the law and apply it faithfully."}]},{"t":"law","label":"guidelines, and rules: PROTECT Act, Pub. L. No. 108-21","url":"https://www.govinfo.gov/link/plaw/108/public/21","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(a)(1)","(a)(3)","(b)(3)","(e)(3)(A)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31, 32, 32, 35, 20, 35, 20, 20"},"q":[{"src":"brief","b":1,"text":"was imposed in violation of law.","cite":"18 U.S.C. 3742(a)(1)"}]},{"t":"usc","label":"18 U.S.C. § 3161","url":"https://www.law.cornell.edu/uscode/text/18/3161","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 3162","url":"https://www.law.cornell.edu/uscode/text/18/3162","subs":["(a)(2)"],"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"[i]n determining whether to dismiss the case with or without prejudice.","cite":"18 U.S.C. 3162(a)(2)"}]},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"1":"30"}},{"t":"case","label":"Arave v. Creech","cite":"507 U.S. 463","y":1993,"id":"1992/91-1160","sc":1,"by":{"2":"8"}},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"2":"12"}},{"t":"case","label":"Bond v. United States","cite":"134 S. Ct. 2077","y":2014,"id":"2013/12-158","sc":1,"by":{"2":"14"}},{"t":"case","label":"California v. Taylor","cite":"353 U.S. 553","y":1957,"id":"1956/385","sc":1,"by":{"2":"11"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Echazabal","cite":"536 U.S. 73","y":2002,"id":"2001/00-1406","sc":1,"by":{"2":"12"}},{"t":"case","label":"Duignan v. United States","cite":"274 U.S. 195","y":1927,"id":"scdb/1926-059","sc":1,"by":{"2":"11"}},{"t":"case","label":"Lambrix v. Singletary","cite":"520 U.S. 518","y":1997,"id":"1996/96-5658","sc":1,"by":{"2":"8"}},{"t":"case","label":"Marx v. Gen. Rev. Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"2":"14"}},{"t":"case","label":"Sochor v. Florida","cite":"504 U.S. 527","y":1992,"id":"1991/91-5843","sc":1,"by":{"2":"8"}},{"t":"case","label":"United States v. Burrell","cite":"622 F.3d 961","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/622/961/","by":{"2":"5, 17"}},{"t":"case","label":"United States v. Thomas","cite":"498 F.3d 336","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/498/336/","by":{"2":"18"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"by":{"2":"12"}},{"t":"case","label":"United States v. Washington","cite":"759 F.3d 1175","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/759/1175/","by":{"2":"11"}},{"t":"case","label":"United States v. Watkins","cite":"625 F.3d 277","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/625/277/","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Crim. P. 32.1","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32.1","by":{"2":"13"}}]};